    public static function row($table,$id,$lock=false) { global $wpdb;return self::uuid($id)?$wpdb->get_row($wpdb->prepare('SELECT * FROM '.self::table($table).' WHERE id=%s'.($lock?' FOR UPDATE':''),$id)):null; }
