        $actions=['tours/(?P<id>[a-f0-9-]{36})/versions'=>'create_version','tour-versions/(?P<id>[a-f0-9-]{36})/review'=>'review_version','tour-departures/(?P<id>[a-f0-9-]{36})/review'=>'review_departure','tour-departures/(?P<id>[a-f0-9-]{36})/refresh'=>'refresh_departure','tour-departures/(?P<id>[a-f0-9-]{36})/room-plan'=>'configure_rooms','tour-departures/(?P<id>[a-f0-9-]{36})/changes'=>'propose_change','tour-changes/(?P<id>[a-f0-9-]{36})/consent'=>'consent','tour-changes/(?P<id>[a-f0-9-]{36})/resolve'=>'resolve_change','tour-changes/(?P<id>[a-f0-9-]{36})/apply'=>'apply_change','tour-departures/(?P<id>[a-f0-9-]{36})/documents'=>'review_documents','tour-departures/(?P<id>[a-f0-9-]{36})/rooming'=>'assign_room','tour-departures/(?P<id>[a-f0-9-]{36})/operations'=>'record_operation','tour-operations/(?P<id>[a-f0-9-]{36})/review'=>'review_operation','tour-departures/(?P<id>[a-f0-9-]{36})/operation-state'=>'operation_state'];foreach ($actions as $path=>$method) register_rest_route('agency/v1','/'.$path,['methods'=>'POST','permission_callback'=>[__CLASS__,'permission'],'callback'=>static function($r) use ($method) { $body=$r->get_json_params();return self::response(is_array($body)&&!array_is_list($body)?self::$method($r['id'],$body,(string)$r->get_header('Idempotency-Key')):self::error('atlas_invalid_request','JSON object required.','اطلاعات ساختاری لازم است.')); }]);
        register_rest_route('agency/v1','/tour-departures/(?P<id>[a-f0-9-]{36})',['methods'=>'GET','permission_callback'=>'__return_true','callback'=>static fn($r)=>self::response(self::public_departure($r['id']))]);register_rest_route('agency/v1','/tour-versions/(?P<id>[a-f0-9-]{36})',['methods'=>'GET','permission_callback'=>[__CLASS__,'permission'],'callback'=>static fn($r)=>self::response(self::version($r['id']))]);register_rest_route('agency/v1','/tour-changes',['methods'=>'GET','permission_callback'=>[__CLASS__,'permission'],'callback'=>static fn()=>self::response(self::customer_changes())]);
        register_rest_route('agency/v1','/tour-departures/(?P<id>[a-f0-9-]{36})/manifest',['methods'=>'POST','permission_callback'=>[__CLASS__,'permission'],'callback'=>static function($r) { $b=$r->get_json_params();return self::response(is_array($b)&&self::body_keys($b,['page','limit','purpose'])?self::manifest($r['id'],$b['page']??null,$b['limit']??null,$b['purpose']??null):self::error('atlas_invalid_request','Explicit manifest purpose and pagination required.','هدف مشخص فهرست و صفحه‌بندی لازم است.')); }]);
    }
    private static function display_time($instant,$zone,$day,$time) {
        if (self::utc($instant)&&is_string($zone)&&in_array($zone,timezone_identifiers_list(),true)) return (new DateTimeImmutable($instant))->setTimezone(new DateTimeZone($zone))->format('Y-m-d H:i P').' ['.$zone.']';
        return self::t('Day ','روز ').$day.' '.$time.' ['.$zone.']';
    }
    private static function schedule_html(array $p) {
        $html='<section class="atlas-tour-itinerary"><h3>'.esc_html(self::t($p['title_en'],$p['title_fa'])).'</h3><p>'.esc_html(self::t($p['description_en'],$p['description_fa'])).'</p><p>'.esc_html(self::t('Age / group limits: ','مرزهای سن و گروه: ').$p['age_min'].'–'.$p['age_max'].' / '.$p['group_min'].'–'.$p['group_max']).'</p><p>'.esc_html(self::t($p['fitness_en'],$p['fitness_fa'])).'</p><p>'.esc_html(self::t($p['accessibility_en'],$p['accessibility_fa'])).'</p><ol>';foreach ($p['stops'] as $s) $html.='<li>'.esc_html($s['city'].' · '.$s['country'].' · '.self::display_time($s['arrival_at']??null,$s['timezone'],$s['arrival_day'],$s['arrival_time']).' → '.self::display_time($s['departure_at']??null,$s['timezone'],$s['departure_day'],$s['departure_time'])).'<p>'.esc_html(self::t($s['meeting_en'],$s['meeting_fa'])).'</p><p>'.esc_html(self::t($s['contingency_en'],$s['contingency_fa'])).'</p></li>';$html.='</ol><ul>';foreach ($p['legs'] as $leg) $html.='<li>'.esc_html($p['stops'][$leg['origin']]['city'].' → '.$p['stops'][$leg['destination']]['city'].' · '.$leg['mode'].' · '.self::display_time($leg['depart_at']??null,$leg['depart_zone'],$leg['depart_day'],$leg['depart_time']).' → '.self::display_time($leg['arrive_at']??null,$leg['arrive_zone'],$leg['arrive_day'],$leg['arrive_time'])).'</li>';foreach ($p['activities'] as $item) $html.='<li>'.esc_html(self::display_time($item['starts_at']??null,$item['timezone'],$item['start_day'],$item['start_time']).' → '.self::display_time($item['ends_at']??null,$item['timezone'],$item['end_day'],$item['end_time']).' · '.self::t($item['description_en'],$item['description_fa']).' · '.($item['included']?self::t('included','شامل'):self::t('excluded','خارج از قیمت'))).' · '.esc_html($item['meal']).'</li>';foreach ($p['lodging'] as $stay) $html.='<li>'.esc_html(self::t($stay['room_type_en'],$stay['room_type_fa']).' · '.$stay['nights'].' '.self::t('nights','شب').' · '.$stay['occupancy'].' · '.self::t($stay['meals_en'],$stay['meals_fa'])).'</li>';$html.='</ul>';foreach (['inclusions'=>self::t('Inclusions','خدمات شامل'),'exclusions'=>self::t('Exclusions','خدمات خارج از قیمت'),'equipment'=>self::t('Required equipment','وسایل لازم'),'documents'=>self::t('Required documents; manual operations review','مدارک لازم؛ بازبینی دستی عملیات')] as $key=>$label) $html.='<p><strong>'.esc_html($label).':</strong> '.esc_html(implode(' · ',$p[$key])).'</p>';return $html.'<p><strong>'.esc_html(self::t('Cancellation terms','شرایط لغو')).':</strong> '.esc_html(self::t($p['cancellation_en'],$p['cancellation_fa'])).'</p></section>';
    }
    public static function details($html,$offer) { $d=self::for_offer((int)$offer['id']);if (!$d||$d->state!=='scheduled') return $html;$data=json_decode($d->payload,true);return $html.'<p>'.esc_html(self::t('Reviewed local departure; supplier allocations are manually managed. Payment and agency booking confirmation remain separate.','سفر محلی بازبینی‌شده؛ تخصیص تأمین‌کننده دستی مدیریت می‌شود. پرداخت و تأیید رزرو آژانس جدا هستند.')).'</p>'.self::schedule_html($data['schedule']); }
    public static function booking_fields($html,$offer) { if (($offer['kind']??'')!=='tour') return $html;$d=self::for_offer((int)$offer['id']);if (!$d) return $html;$p=json_decode($d->payload,true)['schedule'];$html.='<fieldset data-tour-terms><legend>'.esc_html(self::t('Reviewed tour terms and travelers','شرایط بازبینی‌شده تور و مسافران')).'</legend><input type="hidden" name="tour_terms_version" data-atlas-booking-option value="'.esc_attr($d->version_id).'"><label><input type="checkbox" name="tour_terms_accepted" data-atlas-booking-option data-value-type="bool" required>'.esc_html(self::t('I accept the displayed itinerary, inclusions, fitness/accessibility information and cancellation terms for this version.','برنامه، خدمات شامل، اطلاعات آمادگی و دسترس‌پذیری و شرایط لغو نمایش‌داده‌شده این نسخه را می‌پذیرم.')).'</label>';if ($p['documents']) $html.='<label><input type="checkbox" name="tour_documents_attested" data-atlas-booking-option data-value-type="bool" required>'.esc_html(self::t('I self-attest the listed document requirements for each traveler. Agency manual review is still required before operation.','الزامات مدارک فهرست‌شده هر مسافر را خوداظهاری می‌کنم. پیش از عملیات بازبینی دستی آژانس همچنان لازم است.')).'</label>';return $html.'</fieldset>'; }
    private static function open($operation,$id='',$hidden=[],$builder=false) { $html='<form method="post" '.($builder?'data-tour-structured':'').' action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="atlas_tour"><input type="hidden" name="operation" value="'.esc_attr($operation).'"><input type="hidden" name="object_id" value="'.esc_attr($id).'"><input type="hidden" name="idempotency_key" value="'.esc_attr(wp_generate_uuid4()).'"><input type="hidden" name="lang" value="'.esc_attr(($_GET['lang']??'')==='fa'?'fa':'en').'">'.wp_nonce_field('atlas_tour','_wpnonce',true,false);foreach ($hidden as $key=>$value) $html.='<input type="hidden" data-tour-field="'.esc_attr($key).'" name="body['.esc_attr($key).']" value="'.esc_attr($value).'">';return $html; }
    private static function input($key,$en,$fa,$value='',$type='text',$required=true) { return '<label>'.esc_html(self::t($en,$fa)).'<input data-tour-field="'.esc_attr($key).'" data-tour-type="'.($type==='number'?'int':'text').'" name="body['.esc_attr($key).']" type="'.esc_attr($type).'" value="'.esc_attr($value).'" '.($required?'required':'').'></label>'; }
    private static function area($key,$en,$fa,$lines=false,$value='') { return '<label>'.esc_html(self::t($en,$fa)).'<textarea data-tour-field="'.esc_attr($key).'" data-tour-type="'.($lines?'lines':'text').'" name="body['.esc_attr($key).']">'.esc_textarea($value).'</textarea></label>'; }
