    private static function repeat($name,$en,$fa,$row) { return '<fieldset data-tour-repeat="'.esc_attr($name).'"><legend>'.esc_html(self::t($en,$fa)).'</legend><div data-tour-rows></div><template><section data-tour-row>'.$row.'<button type="button" data-tour-up>'.esc_html(self::t('Move up','بالا')).'</button><button type="button" data-tour-down>'.esc_html(self::t('Move down','پایین')).'</button><button type="button" data-tour-remove>'.esc_html(self::t('Remove row','حذف ردیف')).'</button></section></template><button type="button" data-tour-add>'.esc_html(self::t('Add row','افزودن ردیف')).'</button></fieldset>'; }
    private static function time_fields($prefix,$en,$fa,$zone=false) { return self::input($prefix.'_day',$en.' day (1–100)',$fa.' روز (۱ تا ۱۰۰)',1,'number').self::input($prefix.'_time',$en.' local HH:MM',$fa.' محلی HH:MM','09:00').($zone?self::input($prefix.'_zone',$en.' IANA zone',$fa.' منطقه IANA','UTC'):''); }
    private static function bool_field($name,$en,$fa) { return '<label><input type="checkbox" data-tour-field="'.esc_attr($name).'" data-tour-type="bool" name="body['.esc_attr($name).']">'.esc_html(self::t($en,$fa)).'</label>'; }
    private static function builder($definition,$latest) {
