        $fold=self::select('fold_policy','Repeated local hour','ساعت محلی تکراری',['reject'=>['Reject ambiguity','رد ابهام'],'earlier'=>['Earlier offset','ساعت زودتر'],'later'=>['Later offset','ساعت دیرتر']]);$stop=self::input('city','City','شهر').self::input('country','Country','کشور').self::input('timezone','IANA zone','منطقه IANA','UTC').self::time_fields('arrival','Arrival','ورود').self::time_fields('departure','Departure','خروج').self::area('meeting_en','Meeting point EN','محل ملاقات انگلیسی').self::area('meeting_fa','Meeting point FA','محل ملاقات فارسی').self::area('contingency_en','Contingency EN','جایگزین انگلیسی').self::area('contingency_fa','Contingency FA','جایگزین فارسی').self::bool_field('overnight','Overnight stay','اقامت شب').$fold;$html.=self::repeat('stops','Ordered stops (keyboard reorder)','توقف‌های مرتب (مرتب‌سازی با صفحه‌کلید)',$stop);
        $leg=self::input('origin','Origin stop index (first is 0)','شماره توقف مبدا (اولین ۰)',0,'number').self::input('destination','Next destination stop index','شماره توقف بعدی مقصد',1,'number').self::select('mode','Transport type','نوع حمل‌ونقل',['walk'=>['Walk','پیاده'],'road'=>['Road','جاده'],'rail'=>['Rail','قطار'],'air'=>['Air','هوایی'],'water'=>['Water','آبی'],'other'=>['Other','سایر']]).self::time_fields('depart','Departure','خروج',true).self::time_fields('arrive','Arrival','ورود',true).self::input('connection_buffer_minutes','Required connection buffer minutes','دقایق مهلت اتصال لازم',60,'number').self::area('luggage_en','Luggage EN','بار انگلیسی').self::area('luggage_fa','Luggage FA','بار فارسی').$fold;$html.=self::repeat('legs','Transport legs; stop indices must match order','بخش‌های حمل‌ونقل؛ شماره توقف باید با ترتیب منطبق باشد',$leg);
        $activity=self::select('type','Activity type','نوع فعالیت',['visit'=>['Visit','بازدید'],'transport'=>['Transport','حمل‌ونقل'],'meal'=>['Meal','غذا'],'free_time'=>['Free time','وقت آزاد'],'other'=>['Other','سایر']]).self::area('description_en','Activity EN','فعالیت انگلیسی').self::area('description_fa','Activity FA','فعالیت فارسی').self::time_fields('start','Start','شروع').self::time_fields('end','End','پایان').self::input('timezone','IANA zone','منطقه IANA','UTC').self::input('meal','Meal details','جزئیات غذا','', 'text',false).self::area('equipment','Equipment; one per line','وسایل؛ هر کدام در یک خط',true).self::bool_field('included','Included in public price','شامل قیمت عمومی').$fold;$html.=self::repeat('activities','Timed activities','فعالیت‌های زمان‌دار',$activity);
        $lodging=self::input('stop_index','Stop index (first is 0)','شماره توقف (اولین ۰)',0,'number').self::input('check_in_day','Check-in day','روز ورود',1,'number').self::input('nights','Number of nights','تعداد شب',1,'number').self::input('occupancy','Maximum room occupancy','حداکثر ظرفیت اتاق',2,'number').self::input('room_type_en','Room type EN','نوع اتاق انگلیسی').self::input('room_type_fa','Room type FA','نوع اتاق فارسی').self::input('meals_en','Meals EN','غذا انگلیسی','', 'text',false).self::input('meals_fa','Meals FA','غذا فارسی','', 'text',false);$html.=self::repeat('lodging','Lodging nights, rooms and meals','شب‌های اقامت، اتاق‌ها و غذا',$lodging);
