    private static function review_controls($operation,$id,$revision=null,$warnings=[]) { $html=self::open($operation,$id,$revision===null?[]:['expected_revision'=>$revision]);$html.=self::select('state','Review transition','گذار بازبینی',$operation==='review_version'?['submitted'=>['Submit immutable version','ارسال نسخه تغییرناپذیر'],'approved'=>['Approve independently','تأیید مستقل'],'rejected'=>['Reject','رد']]:['submitted'=>['Submit departure','ارسال سفر'],'scheduled'=>['Approve independent departure','تأیید مستقل سفر'],'rejected'=>['Reject','رد']]);return $html.self::area('accepted_warnings','Exact warning codes accepted, one per line','کد هشدارهای پذیرفته‌شده، هر کدام در یک خط',true,implode("\n",$warnings)).self::input('reason','Review rationale','دلیل بازبینی').self::submit('Record transition','ثبت گذار'); }
    private static function customer_panel($html) { foreach (self::customer_changes() as $row) { $p=json_decode($row['payload'],true);$html.='<article data-tour-change="'.esc_attr($row['change_id']).'"><h3>'.esc_html(self::t('Tour change notice','اطلاعیه تغییر تور')).' · '.esc_html((string)$row['revision']).'</h3><p>'.esc_html(self::t($p['message_en'],$p['message_fa'])).'</p><p><bdi>'.esc_html($row['booking_id']).'</bdi> · '.esc_html($row['state']).'</p><p>'.esc_html(self::t('The original booking snapshot remains intact. This decision performs no refund or transfer.','نسخه اصلی رزرو حفظ می‌شود. این تصمیم بازپرداخت یا انتقال انجام نمی‌دهد.')).'</p><details><summary>'.esc_html(self::t('Original itinerary','برنامه اصلی')).'</summary>'.self::schedule_html($p['old_schedule']).'</details>';if (isset($p['new_schedule'])) $html.='<details><summary>'.esc_html(self::t('Proposed replacement itinerary','برنامه جایگزین پیشنهادی')).'</summary>'.self::schedule_html($p['new_schedule']).'</details>';if ($row['state']==='pending'&&in_array($row['change_state'],['pending_consent','canceled'],true)) $html.=self::open('consent',$row['change_id'],['booking_id'=>$row['booking_id']]).self::select('decision','My explicit decision','تصمیم مشخص من',$row['change_state']==='canceled'?['acknowledged'=>['Acknowledge cancellation notice','مشاهده اطلاعیه لغو']]:['accepted'=>['Agree to proposed replacement','موافقت با جایگزین پیشنهادی'],'declined'=>['Decline; request manual agency contact','رد؛ درخواست تماس دستی آژانس']]).self::submit('Record my decision','ثبت تصمیم من');$html.='</article>'; }return $html; }
    public static function dashboard($html,$customer) {
        global $wpdb;if (!is_user_logged_in()) return $html;wp_enqueue_script('atlas-tours',plugins_url('assets/tours.js',__FILE__),[],'0.1.0',true);$html=self::customer_panel($html);if ($customer||(!self::agency()&&!current_user_can('atlas_manage_records'))) return $html;$html.='<details data-tour-manager><summary>'.esc_html(self::t('Reusable tours, reviewed departures and operations','تورهای قابل استفاده مجدد، سفرهای بازبینی‌شده و عملیات')).'</summary><p>'.esc_html(self::t('Local capacity only. Manual supplier evidence is not a live reservation or legal approval. Do not enter identity numbers, medical details or traveler secrets in operational text.','فقط ظرفیت محلی. شواهد دستی تأمین‌کننده رزرو زنده یا تأیید حقوقی نیست. شماره هویت، جزئیات پزشکی یا اطلاعات محرمانه مسافر را در متن عملیات وارد نکنید.')).'</p>'.self::open('create_definition').self::input('org_id','Organization ID; 0 for a personally owned agency draft','شناسه سازمان؛ ۰ برای پیش‌نویس شخصی آژانس',0,'number').self::input('title','Internal reusable definition title','عنوان داخلی تعریف قابل استفاده مجدد').self::submit('Create reusable definition','ایجاد تعریف قابل استفاده مجدد');
        $page=isset($_GET['tour_page'])&&is_scalar($_GET['tour_page'])?max(1,min(100000,(int)$_GET['tour_page'])):1;$definitions=$wpdb->get_results($wpdb->prepare('SELECT * FROM '.self::table('definitions').' ORDER BY created_at DESC LIMIT 25 OFFSET %d',($page-1)*25));$html.='<ul>';foreach ($definitions as $definition) if (self::can($definition,'read')) $html.='<li><a href="'.esc_url(add_query_arg(['atlas_area'=>'portal','lang'=>($_GET['lang']??'')==='fa'?'fa':'en','tour_definition'=>$definition->id],home_url('/'))).'">'.esc_html($definition->title).'</a> <bdi>'.esc_html($definition->id).'</bdi></li>';$html.='</ul><nav aria-label="'.esc_attr(self::t('Tour definitions pagination','صفحه‌بندی تعریف‌های تور')).'">';if ($page>1) $html.='<a href="'.esc_url(add_query_arg('tour_page',$page-1)).'">'.esc_html(self::t('Previous','قبلی')).'</a> ';$html.=esc_html(self::t('Page ','صفحه ').$page);if (count($definitions)===25) $html.=' <a href="'.esc_url(add_query_arg('tour_page',$page+1)).'">'.esc_html(self::t('Next','بعدی')).'</a>';$html.='</nav>';
        $definitionId=is_string($_GET['tour_definition']??null)?$_GET['tour_definition']:'';$definition=self::row('definitions',$definitionId);if (self::can($definition)) { $latest=(int)$wpdb->get_var($wpdb->prepare('SELECT MAX(version) FROM '.self::table('versions').' WHERE definition_id=%s',$definitionId));$html.='<h3>'.esc_html(self::t('Create a new immutable definition version','ایجاد نسخه تغییرناپذیر جدید تعریف')).'</h3>'.self::builder($definitionId,$latest);$versions=$wpdb->get_results($wpdb->prepare('SELECT * FROM '.self::table('versions').' WHERE definition_id=%s ORDER BY version DESC LIMIT 25',$definitionId));foreach ($versions as $version) { $p=json_decode($version->payload,true);$warnings=json_decode($version->warnings,true);$html.='<article><h3><bdi>'.esc_html($version->id).'</bdi> · '.esc_html($version->version.' · '.$version->state).'</h3>'.self::schedule_html($p).'<p>'.esc_html(self::t('Validation warning codes: ','کد هشدارهای اعتبارسنجی: ').implode(', ',$warnings)).'</p>';if (self::finance()) { $costs=json_decode($version->private_costs,true);$html.='<details><summary>'.esc_html(self::t('Private agency net costs (IRR)','هزینه‌های خالص خصوصی آژانس (IRR)')).'</summary><ul>';foreach ($costs as $cost) $html.='<li><bdi>'.esc_html($cost['category'].' · '.(string)$cost['net_amount_irr'].' IRR · '.$cost['supplier_reference'].' · '.$cost['quote_valid_until']).'</bdi></li>';$html.='</ul></details>'; }if (in_array($version->state,['draft','submitted'],true)) $html.=self::review_controls('review_version',$version->id,null,$warnings);$html.='</article>'; } }
        $html.='<h3>'.esc_html(self::t('Create an independent dated departure','ایجاد سفر تاریخ‌دار مستقل')).'</h3>'.self::open('create_departure','',[],true).self::input('version_id','Approved reusable version ID','شناسه نسخه قابل استفاده مجدد تأییدشده').self::input('offer_id','Matching owned draft tour offer ID','شناسه پیشنهاد تور پیش‌نویس متعلق به خود و منطبق','','number').self::input('date','Local start date (day 1)','تاریخ محلی شروع (روز ۱)','','date').self::area('staff','Explicit staff account IDs, one per line','شناسه حساب کارکنان مشخص، هر کدام در یک خط',true).self::repeat('rooms','Explicit local rooms; not supplier reservations','اتاق‌های محلی مشخص؛ رزرو تأمین‌کننده نیست',self::input('lodging_index','Lodging index (first is 0)','شماره اقامت (اولین ۰)',0,'number').self::input('code','Local room code','کد محلی اتاق').self::input('capacity','Room capacity','ظرفیت اتاق',2,'number')).self::submit('Create departure draft','ایجاد پیش‌نویس سفر');
