        if (self::agency()) $html.=self::open('review_documents',$d->id).self::input('booking_id','Confirmed booking UUID','شناسه رزرو تأییدشده').self::input('attendee_index','Attendee index (first is 1)','شماره مسافر (اولین ۱)',1,'number').self::select('decision','Manual document review','بازبینی دستی مدارک',['reviewed'=>['Evidence manually reviewed','شواهد دستی بازبینی شد'],'rejected'=>['Reject evidence','رد شواهد']]).self::input('evidence_reference','Opaque review evidence; no document numbers','مرجع غیرمعنادار شواهد بازبینی؛ بدون شماره مدرک').self::input('reason','Review reason','دلیل بازبینی').self::submit('Record manual review','ثبت بازبینی دستی');
        $html.=self::open('record_operation',$d->id).self::select('kind','Operational record','رکورد عملیات',['task'=>['Task','وظیفه'],'supplier'=>['Supplier evidence','شواهد تأمین‌کننده'],'incident'=>['Incident reference','مرجع حادثه'],'expense'=>['Expense request; no transfer','درخواست هزینه؛ بدون انتقال پول']]).self::area('description','Brief operational description; no personal or medical details','توضیح کوتاه عملیات؛ بدون جزئیات شخصی یا پزشکی').self::input('evidence_reference','Opaque evidence reference','مرجع غیرمعنادار شواهد').self::input('amount_irr','Expense only: integer IRR; 0 otherwise','فقط هزینه: IRR صحیح؛ در غیر این صورت ۰',0,'number').self::input('supplier_reference','Supplier only: opaque supplier reference','فقط تأمین‌کننده: مرجع غیرمعنادار','','text',false).self::input('valid_until','Supplier only: evidence valid until UTC ISO, through service end','فقط تأمین‌کننده: اعتبار شواهد UTC ISO تا پایان خدمت','','text',false).self::select('severity','Incident severity; none for other records','شدت حادثه؛ برای سایر رکوردها هیچ',['none'=>['None','هیچ'],'low'=>['Low','کم'],'medium'=>['Medium','متوسط'],'high'=>['High; blocks operation','زیاد؛ عملیات مسدود می‌شود'],'critical'=>['Critical; blocks operation','بحرانی؛ عملیات مسدود می‌شود']]).self::select('supplier_state','Supplier state; none for other records','وضعیت تأمین‌کننده؛ برای سایر رکوردها هیچ',['none'=>['None','هیچ'],'reconfirmed'=>['Manually reconfirmed evidence','شواهد تأیید مجدد دستی'],'withdrawn'=>['Withdrawn; blocks operation','انصراف؛ عملیات مسدود می‌شود']]).self::submit('Record operational evidence','ثبت شواهد عملیات');$records=$wpdb->get_results($wpdb->prepare('SELECT * FROM '.self::table('operations').' WHERE departure_id=%s ORDER BY created_at DESC LIMIT 25',$d->id));foreach ($records as $row) { $html.='<article><bdi>'.esc_html($row->id.' · '.$row->kind.' · '.$row->state).'</bdi>';if ($row->kind!=='expense'||self::finance()) { $p=json_decode($row->payload,true);$html.='<p>'.esc_html($p['descri