        $html.=self::open('operation_state',$d->id).self::select('state','Next operations state','وضعیت بعدی عملیات',['ready'=>['Ready after required checks','آماده پس از بررسی‌های لازم'],'in_progress'=>['Start at scheduled time','شروع در زمان برنامه‌ریزی‌شده'],'completed'=>['Complete after scheduled end','تکمیل پس از پایان برنامه‌ریزی‌شده']]).self::input('reason','Transition reason','دلیل گذار').self::submit('Record operations state','ثبت وضعیت عملیات');
        if (self::agency()) { $html.=self::open('propose_change',$d->id,['expected_revision'=>(int)$d->revision]).self::select('kind','Material change','تغییر مهم',['reschedule'=>['Propose replacement and collect consent','پیشنهاد جایگزین و دریافت رضایت'],'cancel'=>['Cancel operational admission; manual finance follow-up','لغو پذیرش عملیاتی؛ پیگیری دستی مالی']]).self::input('version_id','Approved replacement version ID (reschedule)','شناسه نسخه جایگزین تأییدشده (زمان‌بندی مجدد)','', 'text',false).self::input('date','Replacement local day 1 date','تاریخ محلی روز ۱ جایگزین','', 'date',false).self::area('message_en','Customer notice EN','اطلاعیه مشتری انگلیسی').self::area('message_fa','Customer notice FA','اطلاعیه مشتری فارسی').self::input('reason','Agency reason','دلیل آژانس').self::submit('Record change and close new sales','ثبت تغییر و بستن فروش جدید');$changes=$wpdb->get_results($wpdb->prepare('SELECT * FROM '.self::table('changes').' WHERE departure_id=%s ORDER BY revision DESC LIMIT 25',$d->id));foreach ($changes as $change) { $p=json_decode($change->payload,true);$html.='<article><bdi>'.esc_html($change->id.' · '.$change->state).'</bdi><p>'.esc_html(self::t($p['message_en'],$p['message_fa'])).'</p>';if ($change->state==='pending_consent') { $html.=self::open('resolve_change',$change->id).self::input('booking_id','Unresolved booking to exclude from replacement','رزرو حل‌نشده برای خروج از جایگزین').self::input('evidence_reference','Actual manual resolution reference; no refund is performed','مرجع واقعی حل دستی؛ بازپرداخت انجام نمی‌شود').self::input('reason','Exclusion reason','دلیل خروج').self::submit('Record manual resolution and exclusion','ثبت حل دستی و خروج').self::open('apply_change',$change->id).self::area('accepted_warnings','Reviewed exact warning codes, one per line','کد هشدارهای مشخص بازبینی‌شده، هر کدام در یک خط',true,implode("\n",$p['warnings'])).self::input('reason','Independent review reason','دلیل بازبینی مستقل').self::submit('Apply only after conse