    public static function form() {
        if (!is_user_logged_in()||!check_admin_referer('atlas_tour')) wp_die('Access denied.',403);$op=is_string($_POST['operation']??null)?$_POST['operation']:'';$id=is_string($_POST['object_id']??null)?sanitize_text_field(wp_unslash($_POST['object_id'])):'';$key=is_string($_POST['idempotency_key']??null)?sanitize_text_field(wp_unslash($_POST['idempotency_key'])):'';$raw=isset($_POST['structured_payload'])&&is_string($_POST['structured_payload'])?json_decode(wp_unslash($_POST['structured_payload']),true):null;$body=is_array($raw)?$raw:(is_array($_POST['body']??null)?wp_unslash($_POST['body']):[]);foreach (['org_id','offer_id','expected_latest_version','expected_revision','attendee_index','lodging_index','amount_irr'] as $field) if (isset($body[$field])&&is_string($body[$field])&&preg_match('/^\d{1,15}$/D',$body[$field])) $body[$field]=(int)$body[$field];foreach (['accepted_warnings'] as $field) if (isset($body[$field])&&is_string($body[$field])) $body[$field]=array_values(array_filter(array_map('trim',preg_split('/\R/',$body[$field])),'strlen'));
        $methods=['create_definition','create_version','review_version','create_departure','review_departure','refresh_departure','configure_rooms','propose_change','consent','resolve_change','apply_change','review_documents','assign_room','record_operation','review_operation','operation_state'];if (!in_array($op,$methods,true)) wp_die('Unknown operation.',400);$result=in_array($op,['create_definition','create_departure'],true)?self::$op($body,$key):self::$op($id,$body,$key);if (is_wp_error($result)) wp_die(esc_html($result->get_error_message()),esc_html(self::t('Tour operation unavailable','عملیات تور در دسترس نیست')),['response'=>(int)($result->get_error_data()['status']??422)]);$url=add_query_arg(['atlas_area'=>$op==='consent'?'account':'portal','lang'=>($_POST['lang']??'')==='fa'?'fa':'en','tour_result'=>isset($result['id'])?$result['id']:($result['state']??'saved')],home_url('/'));if ($op==='create_definition') $url=add_query_arg('tour_definition',$result['id'],$url);elseif ($op==='create_version') $url=add_query_arg('tour_definition',$id,$url);elseif ($op==='create_departure') $url=add_query_arg('tour_departure',$result['id'],$url);elseif (in_array($op,['assign_room','review_documents','record_operation','operation_state','propose_change','review_departure'],true)) $url=add_query_arg('tour_departure',$id,$url);wp_safe_redirect($url);exit;
    }
